using UnityEngine; public class StickyNote : MonoBehaviour { public Color hoverColor = Color.white; public Color heldColor = new Color(1f, 0.85f, 0.2f); private Renderer noteRenderer; private Collider noteCollider; private Material runtimeMaterial; private Color baseColor; private Transform homeParent; private Vector3 homePosition; private Quaternion homeRotation; private bool isHeld = false; public CategoryZone CurrentZone { get; set; } void Awake() { Transform body = transform.Find("Body"); if (body == null) { Debug.LogError( name + " does not contain a child named Body." ); return; } noteRenderer = body.GetComponent<Renderer>(); noteCollider = body.GetComponent<Collider>(); if (noteRenderer != null) { runtimeMaterial = noteRenderer.material; baseColor = runtimeMaterial.color; } homeParent = transform.parent; homePosition = transform.position; homeRotation = transform.rotation; } public void SetHighlighted(bool highlighted) { if (isHeld || runtimeMaterial == null) { return; } runtimeMaterial.color = highlighted ? hoverColor : baseColor; } public void SetHeld(bool held) { isHeld = held; if (noteCollider != null) { noteCollider.enabled = !held; } if (runtimeMaterial != null) { runtimeMaterial.color = held ? heldColor : baseColor; } } public void ReturnHome() { CurrentZone = null; transform.SetParent(homeParent); transform.position = homePosition; transform.rotation = homeRotation; isHeld = false; if (noteCollider != null) { noteCollider.enabled = true; } if (runtimeMaterial != null) { runtimeMaterial.color = baseColor; } } }